import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/**
 * Extra cells on a person's row in the people table. A contribution renders one or more <td>s
 * (the slot is a Fragment inside the row's <tr>).
 */
export const PersonRow = defineSlot<{ sheetId: string; user: string; person: Person }>('person.row');
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person's patron: another person on the same sheet (by id). */
export type Patron = { personId: number; patronId: number };

export const patronsKey = (sheetId: string) => ['sheet', sheetId, 'patrons'] as const;

/** Every person's patrons on the sheet. */
export function usePatrons(sheetId: string) {
  return useQuery({
    queryKey: patronsKey(sheetId),
    queryFn: () => getJson<Patron[]>(`/api/sheets/${encodeURIComponent(sheetId)}/patrons`),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { live, useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import type { Person } from '../people/people';
import { personDueTotal, sumDue, useRates } from '../rates/rates';
import { useCap, useFloor, useLate } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';
import { patronsKey, usePatrons } from './patrons';
import type { Patron } from './patrons';

/** A person's patrons (their names, sorted), their backing — the patrons' due-totals added up, skipping n/a;
 *  0.00 with no patrons — and the picker that names one more. */
function PersonPatrons({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId).data ?? [];
  const claims = live(useClaims(sheetId).data ?? [], people);
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const patrons = (usePatrons(sheetId).data ?? [])
    .filter((p) => p.personId === person.id)
    .map((p) => people.find((q) => q.id === p.patronId))
    .filter((p): p is Person => p !== undefined)
    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  const backing = sumDue(patrons.map((p) => personDueTotal(p, claims, rates, today, floor, late, cap)));
  const [chosen, setChosen] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Patron>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/patrons`, { user, patronId }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: patronsKey(sheetId) });
      setChosen('');
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body ? e.body : `Could not name this patron for ${person.name}.`),
    onSettled: once.done,
  });

  return (
    <td>
      Patrons <span data-testid="person-patrons">{patrons.map((p) => p.name).join(', ')}</span>{' '}
      Backing <span data-testid="person-backing">{backing}</span>{' '}
      <select
        data-testid="person-patron-select"
        value={chosen}
        onChange={(e) => {
          setChosen(e.target.value);
          setError('');
        }}
      >
        <option value="">Patron…</option>
        {people.map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>{' '}
      <button
        type="button"
        data-testid="person-patron-add"
        disabled={add.isPending}
        onClick={() => {
          setError('');
          if (chosen === '') {
            setError('Choose a person to name as a patron.');
            return;
          }
          if (!once.start()) return;
          add.mutate(Number(chosen));
        }}
      >
        Add patron
      </button>
      {error && (
        <p data-testid="person-patron-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 46, Component: PersonPatrons });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx response: its status and the text the server sent with it. */
export class HttpError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: string,
  ) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, await res.text());
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

